    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_blurA;
float4 amzSample_blurA(float2 uv) { return float4(amzt_blurA.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
uniform shader amzt_blurB;
float4 amzSample_blurB(float2 uv) { return float4(amzt_blurB.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
uniform shader amzt_blurC;
float4 amzSample_blurC(float2 uv) { return float4(amzt_blurC.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
uniform shader amzt_blurD;
float4 amzSample_blurD(float2 uv) { return float4(amzt_blurD.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_blurA(uv);if(tex==2) return amzSample_blurB(uv);if(tex==3) return amzSample_blurC(uv);if(tex==4) return amzSample_blurD(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_glowAmount;
uniform float amzp_glowRadius;
uniform float amzp_glowSoftness;
uniform float amzp_glowThreshold;
uniform float amzp_glowKnee;
uniform float amzp_hlGlow;
uniform float amzp_hlThreshold;
uniform float amzp_hlWrap;
uniform float amzp_hlSaturation;
uniform float amzp_midGlow;
uniform float amzp_midRange;
uniform float amzp_shGlow;
uniform float amzp_shLift;
layout(color) uniform half4 amzp_glowTint;
uniform float amzp_glowTintStrength;
uniform float amzp_glowWarmth;
uniform float amzp_glowSatBoost;
uniform float amzp_colorPreserve;
uniform float amzp_atmoAmount;
layout(color) uniform half4 amzp_atmoColor;
uniform float amzp_atmoDensity;
uniform float amzp_blendMode;
uniform float amzp_quality;
uniform float amzp_glowOnly;
uniform float amzp_ditherAmt;
uniform float amzp_globalMix;
    float3 toLinear(float3 s) {
        float3 lo = s / 12.92;
        float3 hi = pow((s + 0.055) / 1.055, float3(2.4));
        return mix(lo, hi, step(float3(0.04045), s));
    }
    float3 toSRGB(float3 l) {
        float3 lo = l * 12.92;
        float3 hi = 1.055 * pow(max(l, 0.0), float3(1.0 / 2.4)) - 0.055;
        return mix(lo, hi, step(float3(0.0031308), l));
    }
    float lum(float3 c) {
        return dot(c, float3(0.2126, 0.7152, 0.0722));
    }
    float getTaps(float q) {
        if (q < 1.5) return 10.0;
        if (q < 2.5) return 18.0;
        return 28.0;
    }
    float4 separableBlur(int tex, float2 uv, float2 dir, float radius, float taps) {
        if (radius <= 0.5) return amzTexture(tex, uv);
        float sigma = radius / 2.14596602;
        sigma = max(sigma, 0.00001);
        float baseCoeff = 1.0 / (sqrt(2.0 * 3.14159265359) * sigma);
        float decayRate = exp(-0.5 / (sigma * sigma));
        float decaySq = decayRate * decayRate;
        float4 acc = amzTexture(tex, uv) * baseCoeff;
        float wSum = baseCoeff;
        float coeff = baseCoeff;
        float decay = decayRate;
        for (float i = 1.0; i <= 256.0; i += 2.0) {
            if (i > taps) break;
            float p0 = i;
            float p1 = i + 1.0;
            coeff *= decay;
            wSum += 2.0 * coeff;
            float w0 = coeff;
            coeff *= decay;
            decay *= decaySq;
            wSum += 2.0 * coeff;
            float w1 = coeff;
            float wPair = w0 + w1;
            float oPair = (p0*w0 + p1*w1) / max(wPair, 0.00001);
            float2 uvA = clamp(uv - oPair * dir, 0.0, 1.0);
            float2 uvB = clamp(uv + oPair * dir, 0.0, 1.0);
            acc += amzTexture(tex, uvA) * wPair;
            acc += amzTexture(tex, uvB) * wPair;
        }
        return acc / max(wSum, 0.00001);
    }
    void amzRender() {
        float2 uv = amzScreenNorm();
        float taps = getTaps(float(int(amzp_quality)));
        float r1 = amzp_glowRadius * 0.4;
        float r2 = amzp_glowRadius * 1.2;
        if (amzPass == 0) {
            float2 dir = float2(1.0 / getTexSize((screen.zw/1.0)).x, 0.0);
            amzOutput = separableBlur(0, uv, dir, r1, taps);
            return;
        }
        if (amzPass == 1) {
            float2 dir = float2(0.0, 1.0 / getTexSize((screen.zw/2.0)).y);
            amzOutput = separableBlur(1, uv, dir, r1, taps);
            return;
        }
        if (amzPass == 2) {
            float2 dir = float2(1.0 / getTexSize((screen.zw/1.0)).x, 0.0);
            amzOutput = separableBlur(0, uv, dir, r2, taps);
            return;
        }
        if (amzPass == 3) {
            float2 dir = float2(0.0, 1.0 / getTexSize((screen.zw/2.0)).y);
            amzOutput = separableBlur(3, uv, dir, r2, taps);
            return;
        }
        float4 original = amzTexture(0, uv);
        float3 baseRGB = max(original.rgb, 0.0);
        float3 baseLin = toLinear(baseRGB);
        float baseLum = lum(baseLin);
        float3 narrowBlur = max(amzTexture(2, uv).rgb, 0.0);
        float3 wideBlur = max(amzTexture(4, uv).rgb, 0.0);
        float3 narrowLin = toLinear(narrowBlur);
        float3 wideLin = toLinear(wideBlur);
        float3 softBlur = mix(narrowLin, wideLin, amzp_glowSoftness);
        float softLum = lum(softBlur);
        float knee = max(amzp_glowKnee, 0.00001);
        float edge = softLum - amzp_glowThreshold + knee;
        edge = clamp(edge / (2.0 * knee), 0.0, 1.0);
        edge *= edge;
        float threshMask = max(edge, max(softLum - amzp_glowThreshold, 0.0));
        threshMask = threshMask / max(softLum, 0.00001);
        float3 glowExtract = softBlur * threshMask;
        float3 totalGlow = glowExtract * amzp_glowAmount;
        if (amzp_hlGlow > 0.00001) {
            float hlMask = smoothstep(amzp_hlThreshold - 0.1, amzp_hlThreshold + 0.1, baseLum);
            float3 hlBlur = wideLin * hlMask;
            if (abs(amzp_hlSaturation - 1.0) > 0.00001) {
                float hlL = lum(hlBlur);
                hlBlur = mix(float3(hlL), hlBlur, amzp_hlSaturation);
            }
            totalGlow += hlBlur * amzp_hlGlow * 0.5;
            if (amzp_hlWrap > 0.00001) {
                float wrapMask = smoothstep(amzp_hlThreshold, amzp_hlThreshold + 0.3, baseLum);
                float3 wrapGlow = wideLin * wrapMask * amzp_hlWrap * 0.2;
                totalGlow += wrapGlow;
            }
        }
        if (amzp_midGlow > 0.00001) {
            float midMask = 1.0 - abs(baseLum - 0.5) / max(amzp_midRange, 0.00001);
            midMask = clamp(midMask, 0.0, 1.0);
            midMask *= midMask;
            totalGlow += softBlur * midMask * amzp_midGlow * 0.3;
        }
        if (amzp_shGlow > 0.00001) {
            float shMask = smoothstep(0.3, 0.0, baseLum);
            totalGlow += narrowLin * shMask * amzp_shGlow * 0.2;
            if (amzp_shLift > 0.00001) {
                totalGlow += amzp_shLift * shMask;
            }
        }
        if (amzp_colorPreserve > 0.00001) {
            float glowLum = lum(totalGlow);
            float baseSatRatio = lum(baseLin);
            if (baseSatRatio > 0.00001 && glowLum > 0.00001) {
                float3 baseColor = baseLin / max(baseSatRatio, 0.00001);
                float3 coloredGlow = baseColor * glowLum;
                totalGlow = mix(totalGlow, coloredGlow, amzp_colorPreserve * 0.5);
            }
        }
        if (abs(amzp_glowSatBoost - 1.0) > 0.00001) {
            float gL = lum(totalGlow);
            totalGlow = mix(float3(gL), totalGlow, amzp_glowSatBoost);
        }
        if (abs(amzp_glowWarmth) > 0.00001) {
            totalGlow.r += amzp_glowWarmth * 0.04 * lum(totalGlow);
            totalGlow.b -= amzp_glowWarmth * 0.03 * lum(totalGlow);
        }
        if (amzp_glowTintStrength > 0.00001) {
            float3 tintLin = toLinear(amzp_glowTint.rgb);
            totalGlow = mix(totalGlow, totalGlow * tintLin, amzp_glowTintStrength);
        }
        if (amzp_atmoAmount > 0.00001) {
            float3 atmoLin = toLinear(amzp_atmoColor.rgb);
            float atmoMask = pow(max(lum(softBlur), 0.0), 1.0 + amzp_atmoDensity * 2.0);
            float3 atmosphere = atmoLin * atmoMask;
            totalGlow += atmosphere * amzp_atmoAmount * 0.15;
        }
        totalGlow = max(totalGlow, 0.0);
        if ((amzp_glowOnly>0.5)) {
            float3 glowView = toSRGB(totalGlow);
            amzOutput = float4(clamp(glowView, 0.0, 1.0), 1.0);
            return;
        }
        float3 composited;
        float bm = float(int(amzp_blendMode));
        if (bm < 1.5) {
            composited = baseLin + totalGlow;
        } else if (bm < 2.5) {
            float3 baseS = baseRGB;
            float3 glowS = toSRGB(totalGlow);
            composited = toLinear(1.0 - (1.0 - baseS) * (1.0 - clamp(glowS, 0.0, 1.0)));
        } else if (bm < 3.5) {
            float3 baseS = baseRGB;
            float3 glowS = toSRGB(clamp(totalGlow, 0.0, 1.0));
            float3 r;
            r.r = (glowS.r<0.5) ? 2.0*baseS.r*glowS.r+baseS.r*baseS.r*(1.0-2.0*glowS.r) : 2.0*baseS.r*(1.0-glowS.r)+sqrt(max(baseS.r,0.0))*(2.0*glowS.r-1.0);
            r.g = (glowS.g<0.5) ? 2.0*baseS.g*glowS.g+baseS.g*baseS.g*(1.0-2.0*glowS.g) : 2.0*baseS.g*(1.0-glowS.g)+sqrt(max(baseS.g,0.0))*(2.0*glowS.g-1.0);
            r.b = (glowS.b<0.5) ? 2.0*baseS.b*glowS.b+baseS.b*baseS.b*(1.0-2.0*glowS.b) : 2.0*baseS.b*(1.0-glowS.b)+sqrt(max(baseS.b,0.0))*(2.0*glowS.b-1.0);
            composited = toLinear(r);
        } else {
            float3 baseS = baseRGB;
            float3 glowS = toSRGB(clamp(totalGlow, 0.0, 1.0));
            float3 r;
            r.r = (baseS.r<0.5) ? 2.0*baseS.r*glowS.r : 1.0-2.0*(1.0-baseS.r)*(1.0-glowS.r);
            r.g = (baseS.g<0.5) ? 2.0*baseS.g*glowS.g : 1.0-2.0*(1.0-baseS.g)*(1.0-glowS.g);
            r.b = (baseS.b<0.5) ? 2.0*baseS.b*glowS.b : 1.0-2.0*(1.0-baseS.b)*(1.0-glowS.b);
            composited = toLinear(r);
        }
        float3 fin = toSRGB(max(composited, 0.0));
        if (amzp_ditherAmt > 0.00001) {
            float2 px = floor(getTexSize((screen.zw/1.0)) * uv);
            float n1 = fract(sin(dot(px, float2(12.9898, 78.233))) * 43758.5453);
            float n2 = fract(sin(dot(px, float2(24.123, 17.321))) * 12345.6789);
            float n3 = fract(sin(dot(px, float2(93.989, 67.345))) * 98765.4321);
            fin += (float3(n1, n2, n3) - 0.5) * amzp_ditherAmt;
        }
        fin = mix(baseRGB, fin, amzp_globalMix);
        fin = clamp(fin, 0.0, 1.0);
        amzOutput = float4(fin, original.a);
    }

half4 main(float2 coord) { amzCoord=coord*2.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

